    },
    {
      "location": "Far right of the plot (2021-2023)",
      "fact": "The line shows a steep, sharp increase from 2020 to 2021, reaching its highest vertical peak in 2022, followed by a slight downward slope in 2023."
    },
    {
      "location": "Overall trend",
      "fact": "The end point of the line in 2023 is positioned significantly higher on the page than the starting point in 2012, indicating a general upward trajectory over the decade."
    }
  ],
  "printed_facts": [
    {
      "location": "Top of the image",
      "fact": "The title reads: 'Falling Respiratory Infection Cases in Sentinel Sites from 2012 to 2023'."
